const r = $input.first().json;
const brl = (v) => Number(v).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
const inteiro = (v) => Math.round(Number(v));

const mensagem = `📈 *Relatório mensal fechado — ${r.mes_label}*

` +
  `💰 Margem bruta (venda adicional + complementar + campanha + promoção + recuperação): ${brl(r.margem_total)}
` +
  `📦 Produtos em falta reportados: ${inteiro(r.produtos_em_falta)}
` +
  `🗒️ Pendências dadas baixa: ${inteiro(r.pendencias_baixadas)}
` +
  `👥 Clientes de alto valor recuperados: ${inteiro(r.clientes_recuperados)}

` +
  `Detalhe completo por vendedor: aba Relatório mensal no app.`;

return [{ json: { mensagem } }];
